def candy(ratings):
    n = len(ratings)
    units = [1] * n
    for i in range(1, n):                      # left neighbor rule
        if ratings[i] > ratings[i - 1]:
            units[i] = units[i - 1] + 1
    for i in range(n - 2, -1, -1):             # right neighbor rule
        if ratings[i] > ratings[i + 1]:
            units[i] = max(units[i], units[i + 1] + 1)
    return sum(units)

