#include <bits/stdc++.h>
using namespace std;

int candy(vector<int>& ratings) {
    int n = ratings.size();
    vector<int> units(n, 1);
    for (int i = 1; i < n; ++i)
        if (ratings[i] > ratings[i - 1]) units[i] = units[i - 1] + 1;
    for (int i = n - 2; i >= 0; --i)
        if (ratings[i] > ratings[i + 1]) units[i] = max(units[i], units[i + 1] + 1);
    return accumulate(units.begin(), units.end(), 0);
}

