class Solution {
    public int candy(int[] ratings) {
        int n = ratings.length;
        int[] units = new int[n];
        Arrays.fill(units, 1);
        for (int i = 1; i < n; ++i)
            if (ratings[i] > ratings[i - 1]) units[i] = units[i - 1] + 1;
        for (int i = n - 2; i >= 0; --i)
            if (ratings[i] > ratings[i + 1]) units[i] = Math.max(units[i], units[i + 1] + 1);
        int total = 0;
        for (int u : units) total += u;
        return total;
    }
}
